WITH latest AS (SELECT *, RANK() OVER (PARTITION BY page, session_id ORDER BY duration_sec DESC NULLS LAST) AS rank_in_group FROM web_events QUALIFY rank_in_group = 1) SELECT session_id, CASE WHEN duration_sec >= 528 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_tier, PERCENTILE_APPROX(duration_sec, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_quartiles, COUNT(*) AS cnt, AVG(duration_sec) AS avg_duration_sec, MIN(event_time) AS first_seen, SORT_ARRAY(COLLECT_SET(page)) AS page_list, GROUPING_ID() AS gid FROM latest GROUP BY GROUPING SETS ((session_id, CASE WHEN duration_sec >= 528 THEN 'PREMIUM' ELSE 'STANDARD' END), (session_id)) ORDER BY duration_sec_tier ASC NULLS LAST;
